import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# Kernel for pointwise 2D convolution (kernel size = 1)
# ----------------------------------------------------------------------
conv_kernel_source = """
__global__ void conv1d_kernel(const float* input, const float* weight, const float* bias,
                               int N, int in_channels, int out_channels, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * out_channels * H * W) {
        int b = idx / (out_channels * H * W);
        int rem = idx % (out_channels * H * W);
        int c_out = rem / (H * W);
        int h = rem % (H * W) / W;
        int w = rem % W;

        float sum = 0.0f;
        for (int c_in = 0; c_in < in_channels; ++c_in) {
            // input index: b*in_channels*H*W + c_in*H*W + h*W + w
            int i_in = ((b * in_channels + c_in) * H * W + h) * W + w;
            sum += input[i_in] * (weight[c_out * in_channels + c_in]);
        }
        if (bias != nullptr && bias.size(0) == out_channels) {
            sum += bias[b];
        }
        int out_idx = b * out_channels * H * W + c_out * H * W + h * W + w;
        output[out_idx] = sum;
    }
}
"""

# ----------------------------------------------------------------------
# C++ source for conv1d_cuda
# ----------------------------------------------------------------------
conv1d_cuda_source = """
torch::Tensor conv1d_cuda(torch::Tensor x, int out_channels, int in_channels, int height, int width,
                         const float* weight, const float* bias) {
    auto N = x.size(0);
    auto H = x.size(2);
    auto W = x.size(3);
    auto C_in = x.size(1);

    // Allocate output tensor with zeros
    torch::Tensor out = torch::zeros(N, out_channels, H, W);

    const int block_size = 256;
    const int num_blocks = (N * out_channels * H * W + block_size - 1) / block_size;

    conv1d_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), weight, bias,
                                               N, C_in, out_channels, H, W);

    return out;
}
"""

# ----------------------------------------------------------------------
# Custom CUDA operator for pointwise 2D convolution
# ----------------------------------------------------------------------
conv1d_cuda = load_inline(
    name="conv1d_cuda",
    cpp_sources=conv1d_cuda_source,
    cuda_sources=conv_kernel_source,   # kernel source is needed inside the function; we reuse for brevity.
    functions=["conv1d_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        # Load the custom function
        self.custom_conv = load_inline(
            name="custom_conv",
            cpp_sources=("torch::Tensor conv1d_cuda(torch::Tensor x, int out_channels, int in_channels, int height, int width);"),
            cuda_sources=conv1d_cuda_source,
            functions=["conv1d_cuda"],
            verbose=True,
            extra_cflags=[],
            extra_ldflags=[]
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Default parameters from the original Model (in_channels=64, out_channels=128)
        return self.custom_conv(x, 128, 64, x.size(2), x.size(3))
